window.BANK = {"L": {"L1a": {"part": 1, "groups": [{"type": "gap", "range": [1, 10], "instr": "Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer.", "title": "Hillcrest Leisure Centre: new member form", "rows": ["EX Membership type: off peak", "Surname: [[1]]", "Address: 27 [[2]] Road", "Postcode: [[3]]", "Mobile number: [[4]]", "Preferred contact: by [[5]]", "## Membership details", "Main activity: [[6]]", "Start date: [[7]]", "Monthly fee: £[[8]]", "Payment method: by [[9]]", "Reason for discount: he is a [[10]]"]}], "audio": "audio/L1a.mp3"}, "L1b": {"part": 1, "groups": [{"type": "gap", "range": [1, 10], "instr": "Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.", "title": "Westbrook Museum: volunteer programme", "rows": ["EX Volunteers needed: weekends and school holidays", "Minimum age: [[1]]", "All new volunteers attend a [[2]] session", "## Tasks", "Welcome visitors at the [[3]]", "Help children with [[4]] activities", "Help to update the museum [[5]]", "## Conditions", "Minimum time: [[6]] hours a week", "Free [[7]] in the café", "Travel costs: up to £[[8]] a day", "## Applying", "Contact: Sarah [[9]]", "Bring a copy of your [[10]]"]}], "audio": "audio/L1b.mp3"}, "L2a": {"part": 2, "groups": [{"type": "mcq", "range": [11, 15], "instr": "Choose the correct letter, A, B or C.", "items": [{"q": 11, "stem": "Why was Ashby Park closed for most of last year?", "opts": ["because of flooding", "to build a new lake", "to repair the paths"]}, {"q": 12, "stem": "The new playground is mainly for children aged", "opts": ["under five.", "five to ten.", "over ten."]}, {"q": 13, "stem": "What has changed at the café?", "opts": ["the opening hours", "the outdoor seating", "where the food comes from"]}, {"q": 14, "stem": "Volunteers should remind visitors", "opts": ["not to feed the birds.", "to keep dogs on a lead.", "to take their rubbish home."]}, {"q": 15, "stem": "This summer, the park will mainly offer", "opts": ["concerts.", "a sports day.", "outdoor films."]}]}, {"type": "match", "range": [16, 20], "instr": "Label the map below. Choose the correct letter, A to H, next to questions 16 to 20.", "map": "ashby", "letters": "ABCDEFGH", "items": [{"q": 16, "stem": "Visitor centre"}, {"q": 17, "stem": "Rose garden"}, {"q": 18, "stem": "Boat hire"}, {"q": 19, "stem": "Picnic area"}, {"q": 20, "stem": "Toilets"}]}], "audio": "audio/L2a.mp3"}, "L2b": {"part": 2, "groups": [{"type": "mcq", "range": [11, 14], "instr": "Choose the correct letter, A, B or C.", "items": [{"q": 11, "stem": "Where will the race start this year?", "opts": ["the football stadium", "the town hall", "the river bank"]}, {"q": 12, "stem": "How many runners are expected this year?", "opts": ["about 3,500", "about 2,000", "about 5,000"]}, {"q": 13, "stem": "Volunteers should arrive at the town hall by", "opts": ["7.30.", "8.00.", "6.30."]}, {"q": 14, "stem": "What will every volunteer receive?", "opts": ["a T shirt and a cap", "a free meal", "a free place in next year's race"]}]}, {"type": "mcq2", "range": [15, 16], "instr": "Choose TWO letters, A to E.", "stem": "Which TWO things must volunteers bring?", "opts": ["a water bottle", "photo ID", "sunscreen", "a mobile phone", "a pen"]}, {"type": "match", "range": [17, 20], "instr": "Who will manage each area? Choose the correct letter, A to F, next to questions 17 to 20.", "box": {"title": "Areas", "opts": ["water stations", "first aid", "finish line", "car parking", "lost property", "start line"]}, "items": [{"q": 17, "stem": "Martin"}, {"q": 18, "stem": "Priya"}, {"q": 19, "stem": "Joe"}, {"q": 20, "stem": "Helen"}]}], "audio": "audio/L2b.mp3"}, "L3a": {"part": 3, "groups": [{"type": "mcq", "range": [21, 25], "instr": "Choose the correct letter, A, B or C.", "items": [{"q": 21, "stem": "What first made Maya interested in the topic?", "opts": ["something she saw at work", "a suggestion from their tutor", "a book she read"]}, {"q": 22, "stem": "What was the main problem with the survey?", "opts": ["The questions were unclear.", "It took too long to complete.", "Not enough people replied."]}, {"q": 23, "stem": "What surprised Tom most in the results?", "opts": ["the amount of bread that is wasted", "shoppers' attitude to odd looking fruit", "the rules for supermarket staff"]}, {"q": 24, "stem": "They agree to start the presentation with", "opts": ["a short video.", "a question for the audience.", "a statistic."]}, {"q": 25, "stem": "Doctor Patel's main criticism of the draft was that", "opts": ["the section on methods was too long.", "it needed more visuals.", "the conclusion was weak."]}]}, {"type": "match", "range": [26, 30], "instr": "What do the students decide to do with each section? Choose FIVE answers from the box and write the correct letter, A to F, next to questions 26 to 30.", "box": {"title": "Decisions", "opts": ["remove it completely", "make it shorter", "add examples", "move it to the end", "keep it as it is", "check with the tutor"]}, "items": [{"q": 26, "stem": "the history of supermarkets"}, {"q": 27, "stem": "interviews with store managers"}, {"q": 28, "stem": "government policy"}, {"q": 29, "stem": "solutions from other countries"}, {"q": 30, "stem": "figures on the cost of waste"}]}], "audio": "audio/L3a.mp3"}, "L3b": {"part": 3, "groups": [{"type": "mcq", "range": [21, 24], "instr": "Choose the correct letter, A, B or C.", "items": [{"q": 21, "stem": "What was the students' original aim?", "opts": ["to compare first year and final year students", "to find out whether sleep affects grades", "to test the effect of phones on sleep"]}, {"q": 22, "stem": "Why did they change their plan?", "opts": ["The university would not share students' grades.", "Too few students volunteered.", "Their tutor disliked the idea."]}, {"q": 23, "stem": "How did they record students' sleep?", "opts": ["with wrist trackers", "with a questionnaire", "with sleep diaries"]}, {"q": 24, "stem": "What surprised Ben most?", "opts": ["Students slept longer at weekends.", "Coffee had little effect on results.", "Students forgot to fill in diaries."]}]}, {"type": "mcq2", "range": [25, 26], "instr": "Choose TWO letters, A to E.", "stem": "Which TWO problems with the data do the students mention?", "opts": ["Some diaries were not completed.", "Several students left the study.", "The memory test was too easy.", "Some results were lost.", "The trackers did not work."]}, {"type": "gap", "range": [27, 30], "instr": "Complete the sentences below. Write ONE WORD ONLY for each answer.", "rows": ["The results will be shown in a [[27]].", "The report must say that the [[28]] was small.", "Ben will contact the [[29]] to book a room.", "The report must be handed in on [[30]]."]}], "audio": "audio/L3b.mp3"}, "L4a": {"part": 4, "groups": [{"type": "gap", "range": [31, 40], "instr": "Complete the notes below. Write ONE WORD ONLY for each answer.", "title": "Urban heat islands", "rows": ["## Causes", "Dark surfaces such as roads and [[31]] absorb heat.", "Fewer [[32]] means less cooling through evaporation.", "Heat is released by factories, buildings and [[33]].", "## Effects", "More [[34]] is used during heat waves.", "[[35]] people face the greatest health risk.", "Hot cities have poorer [[36]] quality.", "## Solutions", "Paint roofs and pavements white or other [[37]] colours.", "Green roofs are covered in [[38]].", "Water features such as [[39]] cool the air nearby.", "Main challenge: the [[40]] of maintaining green spaces."]}], "audio": "audio/L4a.mp3"}, "L4b": {"part": 4, "groups": [{"type": "gap", "range": [31, 40], "instr": "Complete the notes below. Write ONE WORD ONLY for each answer.", "title": "Habits", "rows": ["## Definition", "A behaviour performed automatically in a familiar [[31]].", "## The habit loop", "A [[32]] starts the behaviour.", "The behaviour is followed by a [[33]].", "## Research", "Participants are often asked to keep a [[34]].", "## Why habits are hard to break", "They require little [[35]].", "## Changing habits", "Change your [[36]] rather than relying on willpower.", "Make unwanted behaviour less [[37]].", "Connect a new habit to an existing [[38]].", "Begin with very small [[39]].", "Complex behaviours may take [[40]] to become automatic."]}], "audio": "audio/L4b.mp3"}}, "R": {"R1a": {"passage": 1, "title": "The pencil: a short history", "paras": ["Few objects are as familiar, or as easily overlooked, as the ordinary pencil. It is cheap and reliable, and it needs no power or ink. Yet the story of how it came to exist involves geology, war and a surprising amount of chemistry.", "The story begins in the sixteenth century in Borrowdale, a valley in the north of England. Local people discovered a large deposit of an unusual black mineral there, so pure and solid that it could be cut into sticks. Shepherds are said to have used it to mark their sheep. At the time, nobody knew exactly what the substance was. Because it left a dark grey mark similar to that of lead, it was widely believed to be a type of lead, and this mistake explains why we still talk about pencil lead today, even though pencils have never contained the metal. It was not until the eighteenth century that chemists showed that the mineral was a form of carbon, and it was later given the name graphite, from a Greek word meaning to write.", "Borrowdale graphite quickly became valuable. Apart from writing, it was used to line the moulds in which cannonballs were made, which gave it military importance. The mine was guarded, and the amount removed each year was strictly controlled in order to keep prices high.", "The first pencils were simply sticks of graphite, often wrapped in string or sheepskin to keep the user's fingers clean. Graphite is soft and breaks easily, so people soon looked for a better holder. Craftsmen in Italy are thought to have been among the first to place the graphite inside a hollow piece of wood. The method that eventually became standard was to cut a groove into a thin piece of wood, lay the graphite inside it, and glue a second piece of wood on top. Modern pencils are still made in much the same way.", "For many years, England had an almost complete monopoly on good quality graphite. Other countries had deposits, but their graphite was impure and crumbled when it was cut. Pencil makers in Germany, particularly around the city of Nuremberg, tried mixing poor graphite with substances such as sulphur, but the results were disappointing.", "The breakthrough came in France at the end of the eighteenth century. France and Britain were at war, and French supplies of English graphite had been cut off. In 1795, an engineer named Nicolas Jacques Conté developed a new process. He ground graphite into a powder, mixed it with clay and water, shaped the mixture into thin rods and baked them in a kiln. The process had two great advantages. It meant that lower quality graphite could be used, and by changing the proportion of clay, makers could control how hard or soft the pencil was. More clay produced a harder pencil and a lighter line; less clay produced a softer, darker one. The grading system found on pencils today, with letters such as H for hard and B for black, grew out of this idea.", "During the nineteenth century, pencil making became an industry. Factories in Germany and the United States introduced machines to cut the wood and shape the pencils, and prices fell. In 1858, an American named Hymen Lipman received a patent for attaching an eraser to the end of a pencil, although the patent was later declared invalid because a court decided that he had simply combined two existing objects.", "Today, billions of pencils are produced every year. Despite the arrival of computers and tablets, pencils remain popular with artists, builders, students and anyone who needs to write something that can easily be corrected. Perhaps the pencil's greatest strength is the one that made it successful in the first place: it is simple, and it works."], "lettered": false, "groups": [{"type": "tfng", "range": [1, 6], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 1, "stem": "The graphite found at Borrowdale could be cut into sticks without first being processed."}, {"q": 2, "stem": "The term pencil lead is used because early pencils contained some lead."}, {"q": 3, "stem": "Borrowdale graphite was used in the production of weapons."}, {"q": 4, "stem": "The people who worked in the Borrowdale mine were well paid."}, {"q": 5, "stem": "German pencil makers successfully improved poor graphite by adding sulphur."}, {"q": 6, "stem": "Conté's process was first used to make pencils for the French army."}]}, {"type": "gap", "range": [7, 13], "instr": "Complete the notes below. Choose ONE WORD ONLY from the passage for each answer.", "title": "The development of the pencil", "rows": ["## Early pencils", "Graphite sticks were wrapped in string or [[7]].", "Italian craftsmen put graphite inside [[8]] wood.", "## Conté's process", "Graphite powder was mixed with clay and [[9]].", "Rods were baked in a [[10]].", "More clay gave a harder pencil and a [[11]] line.", "## The nineteenth century", "[[12]] were used to cut the wood and shape pencils.", "Lipman's patent was rejected because he had combined two existing [[13]]."]}]}, "R1b": {"passage": 1, "title": "Farming upwards", "paras": ["In a warehouse on the edge of a city, lettuces are growing in rows that reach almost to the ceiling. There is no soil and no sunlight. Instead, the plants sit in trays of water rich in nutrients, under strips of purple and white light. This is a vertical farm, and its supporters believe that farms like it could change the way cities are fed.", "The basic idea is simple. Instead of spreading crops across a large field, a vertical farm stacks them in layers, one above another, inside a building. Because the growing environment is completely controlled, the temperature, humidity and light can be kept at exactly the levels each crop needs. Most vertical farms use a method called hydroponics, in which plant roots grow directly in water containing dissolved minerals. Some use aeroponics, where the roots hang in the air and are sprayed with a fine mist.", "Supporters point to several advantages. The first is the efficient use of space. A building of a few floors can produce as much as a far larger area of open farmland, which matters in places where land is scarce and expensive. The second is water. Because the water in a hydroponic system is collected and reused, vertical farms generally use much less water than traditional farms, where a large proportion is lost through evaporation or drains away into the ground. Third, because the crops are grown indoors, there is little need for pesticides, and harvests are not affected by drought, floods or storms. Crops can be grown all year round, and they can be harvested and delivered to nearby shops on the same day, so they are fresher and need less transport.", "However, vertical farming also faces serious difficulties, and the most important of these is energy. The sun provides outdoor crops with light for free, but indoor farms must pay for every hour of artificial light. The development of LED lamps, which produce light more efficiently than older types of lamp and can be tuned to the colours plants use most, has reduced this cost considerably. Even so, electricity remains one of the largest expenses for most vertical farms, and if that electricity comes from burning fossil fuels, the environmental benefits of the farm may be reduced or even reversed.", "The second difficulty concerns the range of crops. At present, vertical farms grow mostly leafy greens such as lettuce, spinach and herbs, along with some strawberries and tomatoes. These plants grow quickly, are relatively small and sell for a good price. Staple crops such as wheat, rice and potatoes are a different matter. They need a great deal of space and light for the amount of food they produce, and growing them indoors would cost far more than growing them in fields. For the foreseeable future, therefore, vertical farms are likely to supplement traditional agriculture rather than replace it.", "The high cost of setting up a vertical farm is a third problem. The buildings, lighting, climate control systems and sensors are expensive, and several well funded companies have closed after failing to make a profit. Those that survive have often done so by choosing their location carefully, building close to large cities where customers are willing to pay more for fresh, local produce.", "Despite these challenges, many researchers believe vertical farming has a useful role to play. In very cold or very dry regions, where little can be grown outdoors, indoor farms can provide fresh vegetables that would otherwise have to be imported over long distances. Vertical farms are also valuable as research centres, because their controlled conditions allow scientists to study precisely how changes in light or nutrients affect plant growth. What seems clear is that the future of food will not depend on any single technology, but on combining new methods with the best of the old."], "lettered": false, "groups": [{"type": "mcq", "range": [1, 5], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 1, "stem": "What does the writer say about the farm described in the first paragraph?", "opts": ["It is located in the centre of a city.", "It grows plants without soil or natural light.", "It produces mainly purple vegetables.", "It uses water collected from the roof."]}, {"q": 2, "stem": "In aeroponics, plant roots", "opts": ["grow in soil mixed with minerals.", "sit in trays of water.", "are sprayed with a fine mist.", "are kept in complete darkness."]}, {"q": 3, "stem": "According to the writer, why do vertical farms use less water?", "opts": ["Water is recycled within the system.", "The plants need less water to grow.", "The buildings collect rainwater.", "Water is only used at night."]}, {"q": 4, "stem": "What has helped to reduce the cost of lighting?", "opts": ["government support", "longer daylight hours", "solar panels on the roof", "the introduction of LED lamps"]}, {"q": 5, "stem": "Why are staple crops rarely grown in vertical farms?", "opts": ["They are too difficult to harvest.", "Customers prefer them from fields.", "They would be too expensive to grow indoors.", "They need special nutrients."]}]}, {"type": "tfng", "range": [6, 9], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE, FALSE or NOT GIVEN.", "items": [{"q": 6, "stem": "Crops in vertical farms are less likely to be damaged by extreme weather."}, {"q": 7, "stem": "Vertical farms always have a smaller environmental impact than traditional farms."}, {"q": 8, "stem": "Strawberries are the most profitable crop grown in vertical farms."}, {"q": 9, "stem": "Some vertical farming companies have stopped operating."}]}, {"type": "match", "range": [10, 13], "instr": "Complete the summary using the list of words, A to H, below.", "summary": ["Successful vertical farms are often built near large cities, where people will pay more for [[10]] food. In regions with a [[11]] climate, they can reduce the need for [[12]]. They are also useful for [[13]], since conditions inside them can be controlled precisely."], "box": {"title": "", "opts": ["fresh, local", "imports", "research", "harsh", "mild", "cheap", "fertiliser", "tourism"]}, "items": [{"q": 10}, {"q": 11}, {"q": 12}, {"q": 13}]}]}, "R2a": {"passage": 2, "title": "Why we forget", "paras": ["Everyone forgets. We forget names minutes after hearing them, lose track of where we left our keys and struggle to recall facts we studied carefully only weeks earlier. For most people, forgetting feels like a failure, a sign that the memory is not working as it should. Researchers who study memory, however, increasingly see things differently. In their view, forgetting is a normal and even necessary part of how memory works.", "The scientific study of forgetting began in the 1880s with the German psychologist Hermann Ebbinghaus. Ebbinghaus wanted to measure memory without the influence of meaning, since familiar words are easier to remember than unfamiliar ones. He therefore invented hundreds of nonsense syllables, short combinations of letters such as DAX or BOK, and used himself as the only subject. He learned lists of these syllables until he could recite them perfectly, then tested himself again after different periods of time. Instead of simply counting how many syllables he could remember, he measured how much time he saved when he relearned a list compared with learning it the first time. His results produced what is now called the forgetting curve. The greatest loss occurred within the first hour, after which the rate of forgetting slowed down considerably.", "Later researchers asked why forgetting happens, and one important answer is interference. Memories do not exist in isolation, and similar memories can compete with each other. Sometimes old information makes it harder to learn something new, as when a person keeps writing their old address after moving house. At other times, new learning disrupts older memories. Many language learners know this experience: after starting Italian, they find that Spanish words they once knew well are suddenly replaced by Italian ones.", "Research has also shown that the way we study has a strong influence on how much we forget. One of the most reliable findings in psychology is the spacing effect. Information that is studied in several short sessions spread over days or weeks is remembered far better than the same information studied in one long session. Students who leave revision until the night before an examination may remember enough to pass, but much of what they learned will disappear soon afterwards. Many language learning applications now use the spacing effect, reminding users to review words just as they are about to be forgotten.", "A related finding concerns the value of testing. When people try to recall information from memory, for example by answering questions or explaining an idea without looking at their notes, they remember it better than if they simply read it again. Interestingly, students often prefer rereading, because it feels less difficult and gives a comforting sense of familiarity. Yet the effort involved in recalling information appears to be exactly what makes the memory stronger.", "Finally, many researchers argue that forgetting serves a useful purpose. The brain receives an enormous amount of information every day, and remembering all of it would make it harder, not easier, to find what we need. Forgetting where we parked the car last week helps us remember where we parked it today. In this sense, a healthy memory is not one that stores everything, but one that keeps what is important and allows the rest to fade."], "lettered": true, "groups": [{"type": "heading", "range": [14, 19], "instr": "The reading passage has six paragraphs, A to F. Choose the correct heading for each paragraph from the list of headings below.", "box": {"title": "List of headings", "opts": ["The value of being able to forget", "A self experiment with meaningless material", "The best time of day to study", "When old and new memories compete", "Forgetting as a sign of illness", "Spreading learning over time", "A common view of forgetting challenged", "The role of diet in memory", "Remembering by trying to recall"]}, "items": [{"q": 14, "stem": "Paragraph A"}, {"q": 15, "stem": "Paragraph B"}, {"q": 16, "stem": "Paragraph C"}, {"q": 17, "stem": "Paragraph D"}, {"q": 18, "stem": "Paragraph E"}, {"q": 19, "stem": "Paragraph F"}]}, {"type": "gap", "range": [20, 23], "instr": "Complete the summary below. Choose NO MORE THAN TWO WORDS from the passage for each answer.", "title": "The work of Ebbinghaus", "rows": ["Ebbinghaus tested his own memory using lists of [[20]] which he invented so that they would have no meaning. He measured how much time he saved when he [[21]] a list. His results showed that most forgetting happens within the first [[22]], after which the rate of forgetting [[23]]."]}, {"type": "mcq", "range": [24, 26], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 24, "stem": "A language learner who mixes up words from two languages is experiencing", "opts": ["a memory illness.", "interference.", "the spacing effect.", "the testing effect."]}, {"q": 25, "stem": "According to the writer, why do many students prefer rereading?", "opts": ["It feels less difficult.", "It takes less time.", "Teachers recommend it.", "It produces better results."]}, {"q": 26, "stem": "What is the writer's main point in paragraph F?", "opts": ["Most people forget too much.", "Memory becomes weaker with age.", "People should write important things down.", "Forgetting helps the brain to work efficiently."]}]}]}, "R2b": {"passage": 2, "title": "The box that changed the world", "paras": ["Look around the room you are sitting in. The chances are that much of what you can see, from the furniture to the electronic devices, spent part of its journey to you inside a steel box. The shipping container is so ordinary that it is easy to forget how recently it appeared, and how completely it has transformed world trade.", "Before containers, cargo was loaded onto ships piece by piece, in a system known as break bulk shipping. Sacks of coffee, barrels of oil, boxes of fruit and crates of machinery were carried on board by teams of dockworkers and packed into the ship's hold by hand. The process was slow, physically exhausting and dangerous. A ship could spend days or even weeks in port being loaded and unloaded, and goods were frequently damaged or lost through theft along the way.", "The man most often credited with changing this system was an American, Malcolm McLean, who had begun his career driving trucks and went on to build one of the largest trucking companies in the United States. McLean was frustrated by the hours his drivers spent waiting at ports while their loads were transferred to ships, and he began to wonder whether it would be possible to lift the entire back of a truck onto a vessel. In 1956, a converted tanker called the Ideal X sailed from Newark, New Jersey, to Houston, Texas, carrying fifty eight containers. It is widely regarded as the first commercially successful container voyage.", "The early years were far from smooth. Different shipping companies built containers of different sizes, and a box that fitted one company's ships and cranes would not necessarily fit another's. A container could therefore not travel easily between companies or countries, which limited the benefits of the new system. The solution was standardisation. During the late 1960s, international agreements set common sizes for containers and the fittings used to lift and secure them. Even today, the capacity of container ships is measured in a unit based on a standard box twenty feet long.", "The container also changed the geography of ports. Traditional docks were usually close to city centres, with narrow quays and little space for storage. Container shipping required something quite different: huge areas of flat land on which to stack thousands of boxes, giant cranes, good road and rail connections and deep water for ever larger ships. New ports were built away from the old city docks, and in many cities the abandoned waterfront areas were later redeveloped into housing, offices and leisure facilities.", "For dockworkers, the effects were dramatic. Work that had once required large teams could now be done by a handful of crane operators. In port after port, the number of dockworkers fell sharply. Unions resisted the change, and there were long and bitter disputes in a number of countries, but they could not prevent the new technology from spreading.", "Perhaps the most far reaching consequence of the container was its effect on manufacturing. Because transport costs fell so dramatically, it became practical for companies to produce components in one country, assemble them in another and sell the finished product in a third. A pair of trainers might be designed in Europe, made from materials produced in several Asian countries and sold all over the world. Economists still debate how much the container contributed to globalisation, but few doubt that this simple steel box played a central role."], "lettered": true, "groups": [{"type": "match", "range": [14, 18], "instr": "The reading passage has seven paragraphs, A to G. Which paragraph contains the following information? Choose the correct letter, A to G.", "letters": "ABCDEFG", "items": [{"q": 14, "stem": "a description of how goods were handled before containers"}, {"q": 15, "stem": "a reference to old port areas being used for new purposes"}, {"q": 16, "stem": "the reason why one businessman became interested in shipping"}, {"q": 17, "stem": "an explanation of why early containers could not be used everywhere"}, {"q": 18, "stem": "an example of a product made in several different countries"}]}, {"type": "gap", "range": [19, 23], "instr": "Complete the sentences below. Choose ONE WORD ONLY from the passage for each answer.", "rows": ["Before containers, ships often spent days or even [[19]] in port.", "Goods were often lost through [[20]].", "The Ideal X had originally been a [[21]].", "The capacity of container ships is based on a box twenty [[22]] long.", "New ports needed large areas of land and [[23]] water."]}, {"type": "tfng", "range": [24, 26], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE, FALSE or NOT GIVEN.", "items": [{"q": 24, "stem": "McLean began his working life as a truck driver."}, {"q": 25, "stem": "Dockworkers' unions welcomed the introduction of containers."}, {"q": 26, "stem": "The cost of shipping a container has risen steadily since the 1970s."}]}]}, "R3a": {"passage": 3, "title": "Can machines be creative?", "paras": ["For most of history, creativity has been regarded as one of the qualities that most clearly separates human beings from machines. A calculator can add faster than any mathematician, but nobody would say that it had an idea. In recent years, however, computer programs have begun to produce paintings, music, poems and stories that many people find difficult to distinguish from human work. This has revived an old question: can a machine be creative, or is it merely copying?", "Part of the difficulty lies in the word itself. Psychologists who study creativity usually define it as the ability to produce something that is both new and valuable. By this definition, there is a strong case that some programs are already creative. Their output is not a copy of any single existing work, and at least some of it is clearly valued: it is bought, shared and admired. Yet this definition, it seems to me, leaves something out. When we call a person creative, we usually mean more than that they have produced something new and useful. We mean that they intended to do so, that the work expresses something about their experience, and that they understood what they were making.", "Critics of machine creativity focus on precisely these points. A program that generates a poem about grief, they argue, has never lost anyone. It has learned, from an enormous number of examples, which words tend to follow which, and it produces a plausible arrangement of them. The poem may move a reader, but the emotion is supplied entirely by the reader. In this view, the program is less like a poet and more like a very sophisticated mirror, reflecting back the patterns of countless human writers.", "I find this argument persuasive, but only up to a point. It assumes that we know far more about human creativity than we actually do. Human artists also learn by absorbing the work of others; no composer invents music from nothing. And much of what happens when a person has a creative idea is hidden even from that person. Writers frequently report that a character or a line simply arrived, without any conscious effort. If we cannot fully explain where human ideas come from, we should be cautious about declaring with certainty what machines can never do.", "History also suggests caution. When photography was invented in the nineteenth century, some painters predicted the end of their profession. Why would anyone pay for a portrait when a machine could produce a perfect likeness in seconds? In fact, painting did not disappear. Freed from the need to record reality exactly, many artists began to experiment with colour, light and form in ways that had not been possible before. Photography, meanwhile, developed into an art form in its own right. The new technology did not replace human creativity; it changed what human creativity was for.", "None of this means that concern about creative machines is misplaced. There are real questions about fairness when programs are trained on the work of artists who never gave permission and receive no payment. There is a risk, too, that if cheap machine generated content floods the market, skills that take years to develop will be undervalued, and fewer young people will invest the time needed to acquire them. These are economic and ethical problems, and they deserve serious attention from lawmakers.", "But I suspect that the question we began with, whether machines can be creative, is not ultimately the most important one. A more useful question is what people will choose to do with these tools. A program that can produce a hundred melodies in a minute is of little interest in itself. It becomes interesting when a musician selects one, changes it, combines it with something else and places it in a context that gives it meaning. In that process, the human contribution is not removed; it moves to a different place.", "What we value in art has never been only the finished object. We are interested in who made it, why, and under what circumstances. A song written by someone in prison, a painting made by a child, a letter from a soldier: their power comes partly from what we know about the person behind them. For that reason, I expect that work clearly connected to human lives will continue to matter, perhaps even more than before, in a world where impressive surfaces are easy to produce."], "lettered": false, "groups": [{"type": "mcq", "range": [27, 31], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 27, "stem": "In the first paragraph, the writer says that recent computer programs have", "opts": ["proved that machines are more creative than people.", "produced work that is hard to tell apart from human work.", "replaced many professional artists.", "been unable to produce convincing music."]}, {"q": 28, "stem": "According to the second paragraph, the psychologists' definition of creativity", "opts": ["is too complicated to be useful.", "has been rejected by most researchers.", "may suggest that some programs are creative.", "requires a work to be sold."]}, {"q": 29, "stem": "The writer compares a poetry program to a mirror in order to illustrate", "opts": ["the critics' view of how such programs work.", "the writer's own view of human poetry.", "the way readers respond to grief.", "the poor quality of machine poetry."]}, {"q": 30, "stem": "What point does the writer make about human writers in the fourth paragraph?", "opts": ["They rarely learn from other writers.", "They work more slowly than machines.", "They are less creative than they claim.", "They cannot always explain where their ideas come from."]}, {"q": 31, "stem": "The writer mentions photography in order to show that", "opts": ["new technologies can change the role of art.", "painters were right to be worried.", "machines will eventually replace artists.", "portraits are no longer popular."]}]}, {"type": "ynng", "range": [32, 36], "instr": "Do the following statements agree with the claims of the writer in the reading passage? Choose YES if the statement agrees with the claims of the writer, NO if the statement contradicts the claims of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.", "items": [{"q": 32, "stem": "The psychologists' definition fully captures what people mean by creativity."}, {"q": 33, "stem": "The critics' argument about machine creativity is entirely wrong."}, {"q": 34, "stem": "Photography eventually became an art form."}, {"q": 35, "stem": "Governments should ban programs that generate art."}, {"q": 36, "stem": "The value people place on art depends partly on what they know about the artist."}]}, {"type": "match", "range": [37, 40], "instr": "Complete each sentence with the correct ending, A to F, below.", "box": {"title": "", "opts": ["learn by absorbing the work of others.", "could lead to traditional skills being undervalued.", "comes entirely from the reader.", "produce perfect copies of reality.", "began to experiment with colour and form.", "should be protected by new laws."]}, "items": [{"q": 37, "stem": "According to critics, the emotion in a machine poem"}, {"q": 38, "stem": "Human composers, like machines,"}, {"q": 39, "stem": "After the invention of photography, many painters"}, {"q": 40, "stem": "A large amount of cheap machine content"}]}]}, "R3b": {"passage": 3, "title": "The surprising value of boredom", "paras": ["Boredom has a poor reputation. We associate it with long journeys, slow meetings and rainy afternoons, and most of us will go to considerable lengths to avoid it. Today, avoiding boredom has never been easier. A phone in the pocket offers an endless supply of messages, videos and games, so that a moment of waiting at a bus stop or in a queue can be filled almost instantly. Yet a growing number of researchers argue that in eliminating boredom we may be losing something useful.", "To understand why, it helps to consider what boredom actually is. Psychologists generally describe it as an unpleasant state in which a person wants to be engaged in a satisfying activity but cannot find one. It is not the same as simply having nothing to do; people can be bored while busy, for example when their work is repetitive or seems pointless. What makes boredom distinctive is the combination of a desire for stimulation and a lack of it. This, researchers suggest, is exactly what makes it valuable. Boredom functions as a signal, much like hunger or pain. It tells us that our current situation is not meeting our needs and pushes us to look for something better.", "Some of the most interesting evidence concerns creativity. In one well known type of experiment, participants are first given a deliberately dull task, such as copying numbers from a list for a quarter of an hour. They are then asked to think of as many uses as possible for an everyday object, such as a plastic cup. People who have completed the boring task typically produce more ideas, and more original ones, than people who went straight to the creative task. One explanation is that boredom encourages the mind to wander, and that a wandering mind makes unusual connections between ideas.", "Daydreaming, in fact, has been studied extensively in its own right. When we are not focused on a particular task, certain networks in the brain become more active. These networks seem to be involved in remembering the past, imagining the future and thinking about other people. Far from being wasted time, then, the periods when our attention drifts may allow the brain to process experiences and plan ahead.", "None of this means that boredom is always good. Chronic boredom, the kind that persists over long periods, has been linked to a range of problems, including overeating, risky behaviour and poor performance at school or work. The difference seems to lie in what people do in response. Boredom can lead to creativity and reflection, but it can also lead people to reach for whatever stimulation is closest, however unhelpful.", "This is where modern technology becomes relevant. If a phone is always available, the uncomfortable feeling of boredom rarely lasts long enough to push us towards anything new. We do not have time to become curious about our surroundings, to let our minds wander or to start a project, because the screen has already provided a quick distraction. Some researchers worry that this constant stimulation may gradually reduce our tolerance for even mild boredom, making ordinary activities such as reading a long book seem less bearable.", "What, then, should we do? Few experts recommend seeking out boredom deliberately for its own sake. Instead, they suggest allowing it to happen occasionally, rather than escaping it at the first opportunity. Leaving the phone in a bag during a short journey, or sitting quietly for a few minutes before starting work, can create space for the mind to wander. Parents are often advised not to fill every moment of their children's free time with organised activities, since children who have to entertain themselves frequently invent games and stories of their own.", "Boredom, in short, is not a problem to be eliminated but a message to be understood. It tells us that something is missing. Whether we respond by reaching for a screen or by doing something new may depend on how much space we leave for it."], "lettered": false, "groups": [{"type": "ynng", "range": [27, 31], "instr": "Do the following statements agree with the claims of the writer in the reading passage? Choose YES, NO or NOT GIVEN.", "items": [{"q": 27, "stem": "It is easier today than in the past to avoid feeling bored."}, {"q": 28, "stem": "People can only feel bored when they have nothing to do."}, {"q": 29, "stem": "Boredom has a similar function to hunger."}, {"q": 30, "stem": "The creativity experiments described were carried out with children."}, {"q": 31, "stem": "Most experts recommend that people try to feel bored as often as possible."}]}, {"type": "mcq", "range": [32, 35], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 32, "stem": "In the experiment described in the third paragraph, people who did the boring task first", "opts": ["gave up more quickly.", "produced more original ideas.", "preferred the dull task.", "remembered more numbers."]}, {"q": 33, "stem": "According to the fourth paragraph, when our attention drifts, the brain", "opts": ["may process experiences and plan ahead.", "stops working for a short time.", "becomes tired more quickly.", "focuses mainly on the present."]}, {"q": 34, "stem": "What concern about phones does the writer mention in the sixth paragraph?", "opts": ["They are too expensive for young people.", "They cause physical harm.", "They end boredom before it can be useful.", "They are used mainly for games."]}, {"q": 35, "stem": "Parents are advised to", "opts": ["organise more activities for their children.", "limit the time their children spend reading.", "explain boredom to their children.", "let children entertain themselves sometimes."]}]}, {"type": "gap", "range": [36, 40], "instr": "Complete the summary below. Choose ONE WORD ONLY from the passage for each answer.", "title": "Understanding boredom", "rows": ["Psychologists describe boredom as a state in which a person wants [[36]] but cannot find it. It acts as a [[37]] that tells us our situation is not meeting our needs. Boredom may encourage the mind to [[38]], which helps people to make unusual connections. However, the constant use of phones may reduce our [[39]] for mild boredom. Experts suggest leaving a phone in a [[40]] during a short journey."]}]}, "R1c": {"passage": 1, "title": "The bicycle: a two wheeled revolution", "lettered": false, "paras": ["Today there are thought to be more than a billion bicycles in the world, and for millions of people they are the most practical way to get to work or school. Yet the bicycle as we know it took most of the nineteenth century to develop, and several of the early designs were uncomfortable, dangerous or both.", "The earliest ancestor of the modern bicycle appeared in Germany in 1817. Its inventor, Karl Drais, called it a running machine. It had two wheels in a line and a wooden frame, but no pedals. Riders sat on it and pushed themselves along the ground with their feet. Drais hoped it might replace the horse, which was expensive to feed, and on its first public trip he travelled around 13 kilometres in about an hour. The machine attracted attention across Europe, but it was soon banned from the pavements of several cities because riders were a danger to people on foot.", "Pedals arrived several decades later. In the 1860s, French makers began attaching them directly to the front wheel. Because there were no gears, each turn of the pedals produced one turn of the wheel, so the only way to go faster was to make the front wheel larger. The result, in the 1870s, was the high wheeler, later known in Britain as the penny farthing, whose front wheel could be well over a metre across.", "The high wheeler was fast but risky. Riders sat high above the ground, and if the wheel hit a stone they could be thrown forward over the handlebars. As a result, cycling became a sport for young, wealthy and adventurous men rather than a practical way to travel.", "The breakthrough came in 1885, when the English inventor John Kemp Starley produced the Rover. It had two wheels of similar size and a chain that drove the back wheel, which allowed riders to travel quickly without a giant front wheel. Because riders sat lower, they could put their feet on the ground, and the design became known as the safety bicycle. Its basic shape is still used today.", "Comfort improved a few years later. In 1888, John Boyd Dunlop, a Scottish vet living in Ireland, developed a rubber tyre filled with air, reportedly to make his son's tricycle more comfortable. Earlier bicycles had solid tyres and gave riders a rough journey on uneven roads.", "The safety bicycle had important social effects. It was cheaper than a horse and needed no stable, so it gave ordinary workers a new freedom to travel. It was also popular with women, and many historians link it to changes in women's clothing, as long, heavy skirts were replaced by more practical outfits.", "In the twentieth century, cars replaced bicycles as the main form of private transport in many wealthy countries. Recently, however, cycling has become popular again, as cities look for ways to reduce traffic and pollution, and as electric bicycles make longer journeys easier."], "groups": [{"type": "mcq", "range": [1, 4], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 1, "stem": "What did Karl Drais hope his machine would do?", "opts": ["replace the horse", "win races", "carry goods", "help farmers"]}, {"q": 2, "stem": "Why was the running machine banned in some cities?", "opts": ["It was too noisy.", "It frightened horses.", "It was a risk to people walking.", "It damaged the roads."]}, {"q": 3, "stem": "Why did early pedal bicycles have very large front wheels?", "opts": ["to make them more comfortable", "to allow higher speeds", "to make them easier to ride", "to carry more weight"]}, {"q": 4, "stem": "Who mainly rode the high wheeler?", "opts": ["families", "factory workers", "young, rich men", "women"]}]}, {"type": "tfng", "range": [5, 9], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 5, "stem": "The running machine had no pedals."}, {"q": 6, "stem": "The name penny farthing was used from the very beginning."}, {"q": 7, "stem": "The Rover was the first bicycle ever to use a chain."}, {"q": 8, "stem": "Dunlop was trained as a doctor for people."}, {"q": 9, "stem": "The safety bicycle was more expensive to keep than a horse."}]}, {"type": "gap", "range": [10, 13], "instr": "Complete the notes below. Choose ONE WORD ONLY from the passage for each answer.", "title": "The safety bicycle and its effects", "rows": ["The Rover used a [[10]] to drive the back wheel.", "Riders sat lower and could put their [[11]] on the ground.", "Dunlop's tyre was filled with [[12]].", "Women began to wear more practical [[13]] for cycling."]}]}, "R2c": {"passage": 2, "title": "How honeybees share directions", "lettered": true, "paras": ["A honeybee colony depends on a steady supply of nectar and pollen, often collected from flowers more than a kilometre from the hive. Yet most of the bees that visit a new source of food have never been there before. For centuries, beekeepers wondered how these bees knew where to go.", "The answer was discovered by the Austrian scientist Karl von Frisch, who studied bees for most of his career. By placing dishes of sugar water at different distances from hives with glass sides, he was able to watch the bees that returned. He noticed that successful foragers performed repeated movements on the surface of the honeycomb, and that other bees crowded around them. In 1973 he shared the Nobel Prize in Physiology or Medicine for this and related work.", "Von Frisch identified two main dances. When food is close to the hive, a bee performs a round dance, moving in small circles. This tells other bees that food is nearby, but not in which direction. When food is further away, the bee performs a waggle dance. It runs forward in a straight line while shaking its body from side to side, then loops back and repeats the run.", "The waggle dance contains surprisingly precise information. The direction of the straight run shows the direction of the food in relation to the sun. Because the dance takes place in the dark on a vertical surface, the bees use gravity as a reference. A run straight up the comb means fly towards the sun, while a run to the left or right of vertical means fly at the same angle to the left or right of the sun. The length of the run indicates distance: the longer the waggle, the further away the food.", "The dance also allows for time. Since the sun moves across the sky during the day, a bee that dances for a long period gradually changes the angle of its runs. Bees can also navigate on cloudy days, as their eyes can detect patterns of polarised light in the sky that are invisible to humans.", "Not every scientist accepted von Frisch's conclusions at first. Some argued that bees found food mainly by smell. Later experiments, including studies with small robotic bees and radar tracking of individual insects, have largely confirmed that new recruits use the information in the dance, although smell helps them find the exact flowers once they arrive."], "groups": [{"type": "heading", "range": [14, 19], "instr": "The reading passage has six paragraphs, A to F. Choose the correct heading for each paragraph from the list of headings below.", "box": {"title": "List of headings", "opts": ["An early doubt and later evidence", "A long standing question", "Two ways of communicating", "How bees choose which flowers to visit", "Turning the position of the sun into a vertical signal", "Observing bees at artificial food sources", "Allowing for a moving sun and cloudy skies", "The danger of flying too far"]}, "items": [{"q": 14, "stem": "Paragraph A"}, {"q": 15, "stem": "Paragraph B"}, {"q": 16, "stem": "Paragraph C"}, {"q": 17, "stem": "Paragraph D"}, {"q": 18, "stem": "Paragraph E"}, {"q": 19, "stem": "Paragraph F"}]}, {"type": "gap", "range": [20, 23], "instr": "Complete the summary below. Choose NO MORE THAN TWO WORDS from the passage for each answer.", "title": "The waggle dance", "rows": ["The direction of the straight run shows where the food is in relation to the [[20]]. Inside the dark hive, bees use [[21]] as a reference point. The length of the run tells other bees the [[22]] to the food. When new recruits arrive, they use [[23]] to locate the exact flowers."]}, {"type": "mcq", "range": [24, 26], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 24, "stem": "A round dance tells other bees", "opts": ["the exact direction of the food.", "that the food is close to the hive.", "what type of flower to look for.", "that the food has run out."]}, {"q": 25, "stem": "Karl von Frisch received the Nobel Prize", "opts": ["on his own.", "in 1973.", "for his work on smell.", "before he began studying bees."]}, {"q": 26, "stem": "Which method has been used to support von Frisch's ideas?", "opts": ["tracking bees with radar", "painting flowers different colours", "keeping bees away from sunlight", "testing bees' sense of taste"]}]}]}, "R3c": {"passage": 3, "title": "The real value of speaking two languages", "lettered": false, "paras": ["For much of the twentieth century, many parents and teachers believed that bringing up a child with two languages was a mistake. The fear was that the child would become confused, mix the languages and fall behind classmates who spoke only one. Some families who had moved to a new country even stopped using their home language with their children, hoping this would help them succeed at school.", "Research has since shown that these fears were largely unfounded. Children who grow up with two languages may know fewer words in each language at first, but when both languages are counted together, their vocabulary is usually similar to that of children who speak only one. Mixing languages within a sentence, once seen as a sign of confusion, is now widely understood as a normal and often skilful feature of bilingual speech.", "Some researchers went further and claimed that bilingualism brings mental advantages. Because a bilingual person must constantly select one language and keep the other from interfering, it was suggested that their brains receive extra practice in controlling attention. Several studies in the early 2000s reported that bilingual children and adults performed better than monolinguals on tasks that required them to ignore distracting information.", "In recent years, however, this claim has become controversial. Larger studies, involving thousands of participants, have often failed to find any clear difference between bilinguals and monolinguals on such tasks. Critics have also pointed out that studies with positive results were more likely to be published than those that found nothing, which may have created an exaggerated picture. In my view, the honest conclusion is that any advantage in attention, if it exists at all, is probably small.", "Yet focusing on these laboratory tasks risks missing the point. The most important benefits of speaking two languages are not hidden in reaction times but are obvious in everyday life. A second language gives access to other people, other media and, often, other job opportunities. For children of immigrant families, keeping the home language allows them to talk to grandparents and other relatives, and to feel connected to their family history.", "There are also hints of benefits later in life. Some studies have suggested that lifelong bilinguals tend to show the symptoms of dementia several years later than monolinguals, although, as with the research on attention, the findings are not consistent and more work is needed. Nobody should learn a language purely to protect their brain, but it would be a welcome bonus if this effect were confirmed.", "What, then, should parents do? I believe the evidence supports a simple message: if a family speaks more than one language, there is no reason to abandon any of them. Children are capable of learning two languages at once, and the effort needed to maintain a home language is far smaller than the cost of losing it. Schools can help by treating pupils' home languages as a resource rather than a problem.", "Ultimately, the debate about hidden advantages tells us as much about science as about language. A striking result can travel quickly, while the slower work of checking it attracts less attention. The value of bilingualism does not depend on it making people cleverer. It lies in the conversations, relationships and opportunities that two languages make possible."], "groups": [{"type": "ynng", "range": [27, 32], "instr": "Do the following statements agree with the views of the writer in the reading passage? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.", "items": [{"q": 27, "stem": "Families who stopped using their home language were acting on reliable advice."}, {"q": 28, "stem": "Mixing two languages within a sentence can show skill."}, {"q": 29, "stem": "Bilingual children always learn to read earlier than monolingual children."}, {"q": 30, "stem": "Any advantage that bilinguals have in controlling attention is probably small."}, {"q": 31, "stem": "People should learn a second language mainly to protect themselves from dementia."}, {"q": 32, "stem": "Schools should treat pupils' home languages as something useful."}]}, {"type": "mcq", "range": [33, 36], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 33, "stem": "According to the second paragraph, when both languages are counted, the vocabulary of bilingual children is", "opts": ["much larger than that of monolingual children.", "usually similar to that of monolingual children.", "much smaller than that of monolingual children.", "impossible to measure accurately."]}, {"q": 34, "stem": "Why did some researchers think bilinguals might control their attention better?", "opts": ["They constantly choose between two languages.", "They read more books.", "They travel more often.", "They usually start school earlier."]}, {"q": 35, "stem": "What problem with the earlier research do critics mention?", "opts": ["The studies involved too many people.", "Only adults were studied.", "Studies with positive results were more likely to be published.", "The tasks were too difficult."]}, {"q": 36, "stem": "What is the writer's main point in the fifth paragraph?", "opts": ["Laboratory tasks are completely useless.", "Immigrant children should speak only the new language.", "Reaction time is the best way to measure ability.", "The everyday benefits of bilingualism matter most."]}]}, {"type": "match", "range": [37, 40], "instr": "Complete each sentence with the correct ending, A to F, below.", "box": {"title": "", "opts": ["requires less effort than the cost of losing it.", "makes children fall behind at school.", "lies in relationships and opportunities.", "have produced inconsistent results.", "has now been fully proven.", "can spread faster than the work of checking it."]}, "items": [{"q": 37, "stem": "Studies on bilingualism and dementia"}, {"q": 38, "stem": "Keeping a home language"}, {"q": 39, "stem": "A striking scientific result"}, {"q": 40, "stem": "The real value of bilingualism"}]}]}, "R1d": {"passage": 1, "title": "Why coral turns white", "lettered": false, "paras": ["Coral reefs cover less than one percent of the ocean floor, yet they support around a quarter of all marine species. They also protect coastlines from waves and provide food and income for millions of people. In recent decades, however, reefs around the world have been damaged by a process known as bleaching.", "Although coral can look like rock or a plant, it is actually an animal. Each reef is built by thousands of tiny creatures called polyps, which produce hard skeletons of calcium carbonate. Over centuries, these skeletons build up to form the reef.", "Most reef building corals live in partnership with microscopic algae that live inside their tissues. The algae use sunlight to make food through photosynthesis, and they pass much of it to the coral. In return, the coral provides the algae with shelter and some of the nutrients they need. The algae also give many corals their bright colours.", "This partnership is sensitive to temperature. When sea water stays one or two degrees Celsius above its usual summer maximum for several weeks, the relationship breaks down. The coral expels the algae, and because the coral's own tissue is almost transparent, its white skeleton becomes visible. This is what scientists call bleaching.", "A bleached coral is not dead, but it is starving. If temperatures return to normal quickly, the algae can come back and the coral may recover. If the heat lasts too long, the coral is likely to die, and the reef may then become covered in seaweed.", "Mass bleaching events, affecting reefs across whole regions, were first reported in the 1980s. Since then they have become more frequent. Australia's Great Barrier Reef, the largest reef system in the world, has experienced several mass bleaching events since 2016.", "Heat is not the only threat. Pollution from farms and towns, overfishing and damage from boats and divers can all weaken reefs, making them less able to recover after bleaching.", "Scientists are exploring ways to help. Some are breeding corals that can tolerate higher temperatures, while others grow young corals in nurseries and plant them on damaged reefs. However, most experts agree that these projects can only buy time. Without reductions in the greenhouse gas emissions that are warming the oceans, they warn, many reefs will continue to decline."], "groups": [{"type": "gap", "range": [1, 5], "instr": "Complete the notes below. Choose ONE WORD ONLY from the passage for each answer.", "title": "Coral and algae", "rows": ["A reef is built by tiny animals called [[1]].", "Their hard skeletons are made of calcium [[2]].", "The algae inside the coral use [[3]] to make food.", "The algae give many corals their bright [[4]].", "Without the algae, the coral's white [[5]] can be seen."]}, {"type": "tfng", "range": [6, 10], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 6, "stem": "Coral reefs support about a quarter of all marine species."}, {"q": 7, "stem": "A bleached coral has already died."}, {"q": 8, "stem": "Bleaching only happens on the Great Barrier Reef."}, {"q": 9, "stem": "Mass bleaching was first reported before 1950."}, {"q": 10, "stem": "Growing corals in nurseries is cheaper than reducing pollution."}]}, {"type": "mcq", "range": [11, 13], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 11, "stem": "What may happen to a reef where many corals die?", "opts": ["It becomes covered in seaweed.", "It turns red.", "It grows more quickly.", "It moves into deeper water."]}, {"q": 12, "stem": "Which of these is mentioned as a threat to reefs apart from heat?", "opts": ["earthquakes", "overfishing", "cold winters", "strong currents"]}, {"q": 13, "stem": "According to most experts, breeding heat tolerant corals and planting young corals", "opts": ["will solve the problem.", "are too dangerous.", "can only buy time.", "are not necessary."]}]}]}, "R2d": {"passage": 2, "title": "Reading the Rosetta Stone", "lettered": true, "paras": ["In July 1799, French soldiers rebuilding a fort near the town of Rashid, known to Europeans as Rosetta, in the Nile Delta, uncovered a large dark stone covered in writing. The soldiers were part of Napoleon's army in Egypt, which had travelled with a team of scholars, and the importance of the find was recognised almost immediately.", "The stone carries the same text in three scripts. The top section is written in hieroglyphs, the script used mainly for religious and official monuments. The middle section uses Demotic, a script used for everyday documents, and the bottom section is in ancient Greek. The text is a decree issued by a council of priests in 196 BC, confirming the honours given to the young king Ptolemy V.", "Because scholars could read ancient Greek, the stone offered the chance to compare a known language with two unknown scripts. However, the hieroglyphic section is badly damaged, with much of it missing, and progress was slow.", "When the French were defeated in Egypt, the stone passed to the British under the terms of the surrender, and it arrived in London in 1802. It has been displayed in the British Museum almost continuously since then. Egypt has asked for it to be returned.", "Many earlier scholars had assumed that hieroglyphs were symbols representing ideas rather than sounds. One of the first to make real progress was the English scientist Thomas Young, who showed that some hieroglyphs inside oval rings, called cartouches, spelled the name of the king, Ptolemy, using signs that stood for sounds.", "The decisive breakthrough was made by the French scholar Jean François Champollion. Champollion knew Coptic, a later form of the Egyptian language, which helped him link signs to sounds and words. In 1822 he announced that hieroglyphic writing combined signs representing sounds with signs representing whole words or ideas.", "Champollion's work opened up thousands of years of Egyptian history, allowing scholars to read inscriptions on temples, tombs and papyri. Today the phrase Rosetta Stone is often used to describe anything that provides the key to understanding a difficult problem."], "groups": [{"type": "match", "range": [14, 18], "instr": "The reading passage has seven paragraphs, A to G. Which paragraph contains the following information? Choose the correct letter, A to G.", "letters": "ABCDEFG", "items": [{"q": 14, "stem": "the reason scholars thought they could understand the unknown scripts"}, {"q": 15, "stem": "how the stone came to be in another country"}, {"q": 16, "stem": "how the name of the stone is used today"}, {"q": 17, "stem": "a mistaken belief about how hieroglyphs worked"}, {"q": 18, "stem": "the people who found the stone"}]}, {"type": "gap", "range": [19, 22], "instr": "Complete the sentences below. Choose ONE WORD ONLY from the passage for each answer.", "title": "", "rows": ["The middle section of the stone is written in a script called [[19]].", "The decree on the stone was issued by a council of [[20]].", "Young found the name of the king inside oval rings called [[21]].", "Champollion's knowledge of [[22]] helped him connect signs with sounds."]}, {"type": "tfng", "range": [23, 26], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 23, "stem": "The importance of the stone was not understood for many years after it was found."}, {"q": 24, "stem": "The hieroglyphic section of the stone is complete."}, {"q": 25, "stem": "The stone was taken to Paris before it arrived in London."}, {"q": 26, "stem": "Champollion announced his findings in 1822."}]}]}, "R3d": {"passage": 3, "title": "The teenage brain and risk", "lettered": false, "paras": ["Teenagers have long had a reputation for reckless behaviour. They are more likely than children or adults to drive too fast, to try dangerous activities and to make decisions that seem, to an adult observer, hard to explain. For a long time this was blamed on hormones or simply on a lack of experience. Over the past three decades, however, brain imaging has offered a more detailed explanation, and in my view it is one that should change how we treat young people.", "Brain scans have shown that the brain continues to develop well into a person's twenties. One of the last areas to mature is the prefrontal cortex, at the front of the brain, which is involved in planning, controlling impulses and weighing up long term consequences. By contrast, the systems that respond to reward and excitement become especially active around puberty.", "Some researchers describe this as a mismatch: during adolescence, the brain's sensitivity to reward develops faster than its ability to apply the brakes. This may explain why teenagers can make sensible decisions when they are calm, yet behave quite differently in exciting or emotional situations.", "The presence of friends appears to make a particular difference. In one well known experiment, teenagers, young adults and older adults played a driving game on a computer. When playing alone, the three groups took a similar number of risks. When they knew that friends were watching, however, the teenagers took far more risks, while the behaviour of the older adults hardly changed.", "It would be a mistake, though, to conclude that the teenage brain is simply faulty. The same sensitivity to reward that can lead to danger also drives curiosity, the desire to learn new skills and the willingness to leave the safety of the family. From an evolutionary point of view, these are exactly the qualities that young people need in order to become independent.", "Nor does brain research mean that teenagers are not responsible for their actions. Most adolescents, after all, do not take serious risks. What the research does suggest, I would argue, is that adults should think carefully about the situations teenagers are placed in. Rules that limit the number of young passengers new drivers may carry, for example, make sense in light of the experiment described above, and several countries have introduced them.", "Schools and parents can also use what is known about reward. Rather than relying only on warnings about danger, which teenagers often ignore, they can offer young people safe opportunities for excitement and challenge, from sport to drama to outdoor expeditions. Adolescence, seen in this light, is less a problem to be managed than a period of opportunity to be used well."], "groups": [{"type": "ynng", "range": [27, 31], "instr": "Do the following statements agree with the views of the writer in the reading passage? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.", "items": [{"q": 27, "stem": "Brain imaging has given a more detailed explanation of teenage behaviour than earlier ideas."}, {"q": 28, "stem": "Hormones have no effect at all on teenage behaviour."}, {"q": 29, "stem": "The teenage brain should be regarded as simply faulty."}, {"q": 30, "stem": "Brain research shows that teenagers are not responsible for their actions."}, {"q": 31, "stem": "Limiting the number of young passengers that new drivers can carry is sensible."}]}, {"type": "mcq", "range": [32, 35], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 32, "stem": "Which part of the brain is one of the last to mature?", "opts": ["the area at the back of the brain", "the systems that respond to reward", "the prefrontal cortex", "every area at the same time"]}, {"q": 33, "stem": "In the driving game, what happened when friends were watching?", "opts": ["All three groups took more risks.", "The older adults took more risks.", "Nobody changed their behaviour.", "The teenagers took far more risks."]}, {"q": 34, "stem": "According to the writer, sensitivity to reward", "opts": ["only causes problems.", "also encourages curiosity and learning.", "disappears after puberty.", "is stronger in adults."]}, {"q": 35, "stem": "What does the writer recommend in the final paragraph?", "opts": ["giving teenagers safe chances for excitement", "stricter punishments", "more warnings about danger", "keeping teenagers at home"]}]}, {"type": "match", "range": [36, 40], "instr": "Complete the summary using the list of words, A to H, below.", "summary": ["During adolescence, the brain's response to [[36]] develops faster than its ability to control [[37]]. This means that teenagers who make good decisions when they are [[38]] may act differently in emotional situations. The writer argues that adults should pay attention to the [[39]] that teenagers are placed in, and should see adolescence as a time of [[40]]."], "box": {"title": "", "opts": ["situations", "impulses", "punishment", "reward", "calm", "opportunity", "hormones", "experience"]}, "items": [{"q": 36}, {"q": 37}, {"q": 38}, {"q": 39}, {"q": 40}]}]}, "R1e": {"passage": 1, "title": "How tea became Britain's drink", "lettered": false, "paras": ["Tea is so closely linked with British life that it is easy to forget it is a relatively recent arrival. The plant does not grow well in Britain's climate, and for most of the country's history, people drank ale, beer or water rather than tea.", "Tea first reached Europe in the early seventeenth century, carried by Dutch traders from Asia. In Britain, it was being sold in London coffee houses by the 1650s, but it was expensive and was often recommended as a medicine rather than an everyday drink.", "Its popularity among the wealthy grew after 1662, when King Charles II married the Portuguese princess Catherine of Braganza. Catherine was already used to drinking tea, and her habit made it fashionable at court.", "For much of the eighteenth century, tea was heavily taxed. As a result, large amounts were smuggled into the country, and some sellers mixed tea leaves with other plants to make their supplies go further. In 1784, the government greatly reduced the tax on tea, and smuggling quickly stopped being profitable. Tea became affordable for far more people.", "At this time almost all of Britain's tea came from China. In the nineteenth century, however, the British began growing tea on a large scale in India, first in Assam and later in other regions, and then in Ceylon, now Sri Lanka. By the end of the century, most tea drunk in Britain came from these places rather than from China.", "Tea also changed the daily routine. In the 1840s, Anna, Duchess of Bedford, is said to have started taking tea with a light meal in the late afternoon to fill the long gap between lunch and dinner. The habit of afternoon tea spread among her friends and later across society.", "Today, according to industry estimates, people in Britain drink around 100 million cups of tea a day, and most of it is made with tea bags rather than loose leaves."], "groups": [{"type": "tfng", "range": [1, 6], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 1, "stem": "Tea plants grow easily in Britain."}, {"q": 2, "stem": "Tea was first brought to Europe by Dutch traders."}, {"q": 3, "stem": "Catherine of Braganza was the first person to bring tea to Portugal."}, {"q": 4, "stem": "Some sellers added other plants to tea in the eighteenth century."}, {"q": 5, "stem": "After 1784, smuggling tea became more profitable."}, {"q": 6, "stem": "Anna, Duchess of Bedford, was the first person in Britain to drink tea."}]}, {"type": "gap", "range": [7, 13], "instr": "Complete the notes below. Choose ONE WORD AND/OR A NUMBER from the passage for each answer.", "title": "Tea in Britain: key points", "rows": ["1650s: tea sold in London [[7]] houses", "At first, tea was often recommended as a [[8]].", "1662: Charles II married a [[9]] princess.", "[[10]]: the tax on tea was greatly reduced.", "19th century: tea grown on a large scale in [[11]], first in Assam", "Tea was also grown in Ceylon, now called Sri [[12]].", "Today most tea is made with tea [[13]]."]}]}, "R2e": {"passage": 2, "title": "The secret of the gecko's grip", "lettered": true, "paras": ["Geckos are small lizards found in warm regions around the world, and many species can run up smooth walls and even hang upside down from a glass ceiling. For centuries, people wondered how they managed it. Some suggested suction, while others imagined a kind of glue.", "Neither explanation turned out to be correct. Geckos leave no sticky trace behind them, and experiments have shown that they can cling to surfaces in a vacuum, where suction would be impossible.", "The answer lies in the structure of their toes. Each foot is covered in ridges carrying hundreds of thousands of tiny hairs called setae. The end of each seta splits further into hundreds of even smaller tips, called spatulae. Because the tips are so small and so numerous, they can make extremely close contact with a surface.", "At this tiny scale, weak attractive forces between molecules, known as van der Waals forces, become important. Each spatula produces only a minute force, but together the millions of contact points on a gecko's feet produce enough grip to hold far more than the animal's own weight. In 2002, a team led by the American biologist Kellar Autumn published evidence that these forces, rather than water or chemistry, were mainly responsible.", "Just as remarkable is the gecko's ability to let go. Because the hairs grip best when they are pulled at a particular angle, a gecko can release its foot simply by peeling its toes upwards, rather like removing a piece of tape. This allows it to run quickly, attaching and detaching each foot many times a second. The setae also tend to stay clean, as dirt particles stick more strongly to the surface than to the hairs.", "Engineers have tried to copy these features. Researchers have produced gecko tapes and pads covered in tiny artificial hairs, which can hold heavy objects yet be removed without leaving marks. Possible uses include robots that climb walls, grippers that handle delicate objects in factories and devices for collecting rubbish in space. Producing materials that last as long as a gecko's feet and work on rough surfaces, however, remains a challenge."], "groups": [{"type": "match", "range": [14, 17], "instr": "The reading passage has six paragraphs, A to F. Which paragraph contains the following information? Choose the correct letter, A to F.", "letters": "ABCDEF", "items": [{"q": 14, "stem": "a reason why suction cannot explain the gecko's grip"}, {"q": 15, "stem": "a description of how geckos release their feet"}, {"q": 16, "stem": "a list of possible uses for an invention"}, {"q": 17, "stem": "the name of the force mainly responsible for the grip"}]}, {"type": "gap", "range": [18, 22], "instr": "Complete the summary below. Choose NO MORE THAN TWO WORDS from the passage for each answer.", "title": "How a gecko holds on", "rows": ["A gecko's feet are covered in tiny hairs called [[18]], which divide into even smaller tips called [[19]]. These tips make very close contact with a surface, and weak forces between [[20]] then hold the gecko in place. The gecko lets go by [[21]] its toes upwards. Its feet stay clean because dirt sticks more strongly to the [[22]] than to the hairs."]}, {"type": "mcq", "range": [23, 26], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 23, "stem": "What did Kellar Autumn's team show in 2002?", "opts": ["Geckos produce a kind of glue.", "Geckos cannot climb glass.", "Van der Waals forces mainly explain the grip.", "Water is essential to the grip."]}, {"q": 24, "stem": "Why can geckos run quickly up walls?", "opts": ["They can attach and detach each foot many times a second.", "They have very long legs.", "They use their tails to push.", "They jump from one surface to another."]}, {"q": 25, "stem": "Gecko tapes", "opts": ["can only be used once.", "only work in space.", "contain no hairs at all.", "can hold heavy objects and be removed cleanly."]}, {"q": 26, "stem": "What problem with artificial gecko materials is mentioned?", "opts": ["They are too sticky to remove.", "They do not last long and struggle on rough surfaces.", "They are dangerous to use.", "They only work when wet."]}]}]}, "R3e": {"passage": 3, "title": "Giving city centres back to people", "lettered": false, "paras": ["For much of the twentieth century, city planners treated the car as the centre of urban life. Streets were widened, old neighbourhoods were cut through by highways and large areas of land were given over to parking. In many cities, the result is that a large share of public space is reserved for vehicles that spend most of their time standing still.", "A growing number of cities are now trying to reverse this. One of the most frequently cited examples is Pontevedra, a small city in the north west of Spain, which began removing cars from much of its historic centre in 1999. Streets that were once crowded with traffic are now used by pedestrians, and many local people report that the centre feels safer and livelier.", "Larger cities have taken less dramatic steps. Oslo, the capital of Norway, decided not to ban cars completely but removed most of the parking spaces from its central area and replaced them with benches, cycle lanes and small parks. Several other European cities have introduced charges for driving into the centre or have closed particular streets to traffic.", "Supporters of these policies point to clear benefits. Fewer cars mean less noise and air pollution, fewer road accidents and more space for people to meet, play and do business. I find these arguments convincing, especially in dense historic centres where streets were never designed for heavy traffic.", "Critics raise reasonable concerns, however. Shop owners often fear that customers who can no longer park outside will go elsewhere, and this fear should not be dismissed. The evidence on this point is mixed, but several studies have found that pedestrians and cyclists, although they may spend less on each visit, tend to visit more often, so their total spending can match or exceed that of drivers.", "A more serious objection, in my opinion, concerns people who depend on cars. Older people, people with disabilities and workers who need to carry heavy tools cannot always walk, cycle or use public transport. Any plan to reduce traffic must therefore include exceptions and alternatives, such as access for deliveries and disabled drivers and frequent, affordable public transport. Without these, car free centres risk becoming places that only the young and healthy can enjoy.", "It is also worth remembering that a measure that works in one city may not work in another. Pontevedra is compact and flat, while many cities are spread out across large areas with poor public transport. Copying a policy without considering local conditions is unlikely to succeed.", "Nevertheless, I believe the direction of change is right. City centres are among the most valuable spaces a society has, and it is difficult to justify using so much of them to store cars. The challenge is not whether to reduce traffic, but how to do it fairly."], "groups": [{"type": "ynng", "range": [27, 32], "instr": "Do the following statements agree with the views of the writer in the reading passage? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.", "items": [{"q": 27, "stem": "It is hard to justify using so much city centre space for parked cars."}, {"q": 28, "stem": "Pontevedra now has the cleanest air of any city in Spain."}, {"q": 29, "stem": "The worries of shop owners are not worth taking seriously."}, {"q": 30, "stem": "The needs of people who depend on cars are a more serious problem than the concerns of shop owners."}, {"q": 31, "stem": "A policy that succeeds in one city will succeed in any other city."}, {"q": 32, "stem": "Cities should stop trying to reduce traffic in their centres."}]}, {"type": "mcq", "range": [33, 36], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 33, "stem": "What did Oslo do?", "opts": ["It removed most of the parking spaces from its centre.", "It banned all cars from the city.", "It built new highways around the centre.", "It made public transport free."]}, {"q": 34, "stem": "According to several studies, compared with drivers, pedestrians and cyclists", "opts": ["spend more on each visit.", "visit shops more often.", "rarely visit city centres.", "prefer large shopping centres."]}, {"q": 35, "stem": "Why does the writer mention that Pontevedra is compact and flat?", "opts": ["to praise the city's appearance", "to criticise the city's planners", "to explain why its approach may not suit every city", "to encourage tourists to visit"]}, {"q": 36, "stem": "Which of these is the best title for the passage?", "opts": ["The end of the car", "Why city shops are closing", "Spain's urban success story", "Reducing traffic in city centres fairly"]}]}, {"type": "match", "range": [37, 40], "instr": "Complete each sentence with the correct ending, A to F, below.", "box": {"title": "", "opts": ["is how to reduce traffic fairly.", "prefer to shop online.", "treated the car as the centre of urban life.", "may find it hard to walk, cycle or use public transport.", "is whether to reduce traffic at all.", "point to less noise, less pollution and fewer accidents."]}, "items": [{"q": 37, "stem": "Many planners in the twentieth century"}, {"q": 38, "stem": "Supporters of car free centres"}, {"q": 39, "stem": "Workers who carry heavy tools"}, {"q": 40, "stem": "According to the writer, the main challenge for cities"}]}]}, "R1f": {"passage": 1, "title": "London's Great Stink", "lettered": false, "paras": ["In the summer of 1858, London experienced an unusually hot spell, and the River Thames began to smell so badly that the period became known as the Great Stink. For years, the city's waste had flowed into the river, which was also a major source of drinking water.", "London's population had grown rapidly during the first half of the nineteenth century, reaching over two million by 1850. Many homes relied on cesspits, which often overflowed, and the arrival of flushing toilets made things worse by sending even more waste into old drains that emptied into the Thames.", "The city also suffered repeated outbreaks of cholera, which killed tens of thousands of people. At the time, most experts believed the disease was spread by bad air, known as miasma. In 1854, however, the doctor John Snow traced an outbreak in Soho to a single public water pump on Broad Street, suggesting that cholera was spread through contaminated water. His conclusion was not widely accepted for some years.", "The smell of 1858 was particularly unpleasant for members of Parliament, whose building stands beside the river. Curtains were soaked in chemicals in an attempt to block the odour, and within weeks Parliament passed a law giving the Metropolitan Board of Works the power and the money to build a new sewer system.", "The project was led by the board's chief engineer, Joseph Bazalgette. His plan was to build large sewers running parallel to the river, which would collect waste from the existing drains and carry it eastwards, away from the centre, to be released into the Thames further downstream. In total, the system included around 130 kilometres of main sewers and more than a thousand kilometres of smaller street sewers.", "Building the sewers along the river in central London also created the Victoria Embankment, a new road and riverside area built on land reclaimed from the Thames. Bazalgette is said to have made the pipes larger than his calculations required, reasoning that the city would continue to grow.", "The main system was largely completed by the mid 1870s. Cholera outbreaks in the areas it served became much less common, although the last major outbreak in London, in 1866, affected the east of the city, where the system was not yet finished. Many of Bazalgette's sewers are still in use today."], "groups": [{"type": "mcq", "range": [1, 3], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 1, "stem": "Why did the Thames smell especially bad in the summer of 1858?", "opts": ["The weather was unusually hot.", "New factories had been built.", "The river had dried up.", "A ship had sunk in the river."]}, {"q": 2, "stem": "Before John Snow's work, most experts believed cholera was spread by", "opts": ["dirty water.", "bad air.", "animals.", "food from abroad."]}, {"q": 3, "stem": "What did Parliament do after the Great Stink?", "opts": ["It moved to another building.", "It banned flushing toilets.", "It gave a board the power and money to build sewers.", "It closed the pump on Broad Street."]}]}, {"type": "tfng", "range": [4, 8], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 4, "stem": "London's population was over two million by 1850."}, {"q": 5, "stem": "Flushing toilets helped to reduce the amount of waste in the river."}, {"q": 6, "stem": "Snow's conclusion was immediately accepted by other doctors."}, {"q": 7, "stem": "Bazalgette had previously designed sewers for another city."}, {"q": 8, "stem": "Some of Bazalgette's sewers are still used today."}]}, {"type": "gap", "range": [9, 13], "instr": "Complete the summary below. Choose ONE WORD ONLY from the passage for each answer.", "title": "Bazalgette's sewers", "rows": ["Bazalgette planned large sewers running [[9]] to the river, carrying waste [[10]], away from the centre. The work in central London also created a new road called the Victoria [[11]]. Bazalgette is said to have made the pipes larger because he expected the city to [[12]]. The last major cholera outbreak, in 1866, affected the [[13]] of the city."]}]}, "R2f": {"passage": 2, "title": "What happens to memories while we sleep", "lettered": true, "paras": ["It has long been known that people who are deprived of sleep find it harder to concentrate. Over the past few decades, however, researchers have discovered that sleep plays a more active role: it appears to help the brain store and organise memories formed during the day.", "Early evidence came from studies in which people learned lists of words or other material and were then tested after a period of either sleep or wakefulness. Those who had slept usually remembered more. At first, some scientists argued that sleep simply protected memories from interference, since sleeping people are not exposed to new information.", "Later research suggested that more is going on. Sleep is not a single state but consists of several stages that repeat in cycles through the night, including deep, slow wave sleep and rapid eye movement, or REM, sleep. Different stages appear to support different kinds of memory. Deep sleep seems particularly important for remembering facts and events, while REM sleep has been linked to emotional memories and to some kinds of skill learning.", "Studies of animals have provided clues about how this happens. In experiments with rats, scientists recorded the activity of brain cells in the hippocampus, an area involved in memory, while the animals explored a maze. During later sleep, the same patterns of activity appeared again, as if the brain were replaying the experience. Many researchers believe this replay helps to transfer memories to longer term storage in other parts of the brain.", "Sleep may also help people to see connections. In one well known study, participants solved a series of number problems that contained a hidden shortcut. Those who slept between sessions were much more likely to discover the shortcut than those who stayed awake for the same length of time.", "These findings have practical implications, particularly for students. Staying up all night before an exam may provide extra hours of study, but it can reduce the brain's ability to store what has been learned. Spreading study over several days, with a full night's sleep in between, is likely to be far more effective."], "groups": [{"type": "heading", "range": [14, 19], "instr": "The reading passage has six paragraphs, A to F. Choose the correct heading for each paragraph from the list of headings below.", "box": {"title": "List of headings", "opts": ["Advice for people preparing for exams", "An active process rather than a passive one", "Brain cells that repeat earlier activity", "Different stages for different kinds of memory", "Finding a hidden pattern", "Comparing sleepers with people who stayed awake", "The risks of sleeping pills", "Why animals sleep longer than humans"]}, "items": [{"q": 14, "stem": "Paragraph A"}, {"q": 15, "stem": "Paragraph B"}, {"q": 16, "stem": "Paragraph C"}, {"q": 17, "stem": "Paragraph D"}, {"q": 18, "stem": "Paragraph E"}, {"q": 19, "stem": "Paragraph F"}]}, {"type": "tfng", "range": [20, 23], "instr": "Do the following statements agree with the information given in the reading passage? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.", "items": [{"q": 20, "stem": "Some scientists first thought sleep helped memory only by preventing interference."}, {"q": 21, "stem": "REM sleep is the only stage of sleep that affects memory."}, {"q": 22, "stem": "The rats in the experiment were given food when they reached the end of the maze."}, {"q": 23, "stem": "People who slept were more likely to find the hidden shortcut."}]}, {"type": "mcq", "range": [24, 26], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 24, "stem": "The hippocampus is", "opts": ["a stage of sleep.", "an area of the brain involved in memory.", "a type of maze.", "a chemical produced during sleep."]}, {"q": 25, "stem": "According to paragraph C, REM sleep has been linked to", "opts": ["remembering facts and dates.", "falling asleep more quickly.", "emotional memories and some skills.", "waking up early."]}, {"q": 26, "stem": "What does the writer suggest students should do?", "opts": ["study all night before an exam", "sleep during the day instead of at night", "study only in the morning", "spread their study over several days with sleep in between"]}]}]}, "R3f": {"passage": 3, "title": "Can money buy happiness?", "lettered": false, "paras": ["For most of the twentieth century, economists measured a country's success mainly by its income. Gross domestic product, or GDP, became the standard indicator of progress, and politicians promised growth as the route to a better life. In 1974, however, the American economist Richard Easterlin published a paper that raised an awkward question.", "Easterlin found that, within a country at any given time, richer people tended to report being happier than poorer people. Yet when he looked at the United States over several decades, average happiness had hardly changed, even though average income had risen considerably. This apparent contradiction became known as the Easterlin paradox.", "One explanation is that people judge their income partly by comparing it with that of others. If everyone becomes richer together, nobody feels better off than their neighbours. Another is that people quickly adapt to improvements in their circumstances: a pay rise brings pleasure at first, but expectations soon rise to match it.", "The paradox has been heavily debated. Later studies using data from many more countries found that, in general, people in richer countries do report higher satisfaction with their lives, and that this relationship continues even at high levels of income. Some economists argue that Easterlin's original data simply did not cover enough countries or years to show the pattern. Easterlin and his supporters, for their part, maintain that over the long term, growth alone does little to raise happiness.", "My own view is that both sides capture part of the truth. Money clearly matters a great deal to people who lack the basics, such as adequate food, housing and health care. For them, extra income can transform their lives. For those who are already comfortable, however, the gains appear to be smaller, and other factors, such as health, relationships, job security and a sense of purpose, seem to matter at least as much.", "This has important consequences for government policy. If GDP growth does not reliably make people happier, then measuring progress by GDP alone is misleading. Several countries have begun to publish measures of wellbeing alongside traditional economic statistics. Bhutan, for example, has long promoted the idea of Gross National Happiness, and New Zealand introduced a wellbeing budget in 2019.", "Critics warn that happiness is too vague and too easily influenced to guide policy, and that people may answer survey questions differently depending on their mood or culture. These concerns are reasonable, but I do not think they justify ignoring wellbeing altogether. GDP is itself an imperfect measure, and nobody suggests abandoning it. The aim should be to use several indicators together, so that economic growth is treated as a means to a better life rather than an end in itself."], "groups": [{"type": "ynng", "range": [27, 31], "instr": "Do the following statements agree with the views of the writer in the reading passage? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.", "items": [{"q": 27, "stem": "Richard Easterlin was the first economist to study happiness."}, {"q": 28, "stem": "Extra income can make a big difference to people who lack basic needs."}, {"q": 29, "stem": "For people who are already comfortable, health and relationships matter less than money."}, {"q": 30, "stem": "Measuring progress by GDP alone gives a misleading picture."}, {"q": 31, "stem": "Problems with happiness surveys mean that wellbeing should be ignored."}]}, {"type": "mcq", "range": [32, 35], "instr": "Choose the correct letter, A, B, C or D.", "items": [{"q": 32, "stem": "What did Easterlin find when he studied the United States over several decades?", "opts": ["Average happiness hardly changed although income rose.", "Happiness rose as quickly as income.", "Average income fell.", "Poorer people were happier than richer people."]}, {"q": 33, "stem": "Which explanation for the paradox is given in the third paragraph?", "opts": ["Governments hide economic data.", "Surveys are always inaccurate.", "People compare their income with that of others.", "People dislike talking about money."]}, {"q": 34, "stem": "What did later studies using data from more countries find?", "opts": ["There is no link between income and satisfaction.", "People in richer countries report higher life satisfaction.", "Happiness falls once income passes a certain level.", "Only small countries have happy citizens."]}, {"q": 35, "stem": "New Zealand is mentioned as an example of a country that", "opts": ["is very poor.", "invented GDP.", "rejected measures of wellbeing.", "introduced a wellbeing budget."]}]}, {"type": "match", "range": [36, 40], "instr": "Complete the summary using the list of words, A to H, below.", "summary": ["Easterlin's work suggested that rising [[36]] does not always lead to greater happiness. One reason may be that people [[37]] quickly to better conditions. The writer believes money matters most to those who lack the [[38]], and argues that governments should use several [[39]] so that growth is seen as a [[40]] rather than a goal in itself."], "box": {"title": "", "opts": ["indicators", "compete", "income", "means", "surveys", "adapt", "basics", "culture"]}, "items": [{"q": 36}, {"q": 37}, {"q": 38}, {"q": 39}, {"q": 40}]}]}}, "W": {"W1a": {"task": 1, "chart": "museums", "prompt": "The graph below shows the number of visitors to three museums in Northport between 2015 and 2023.", "instr": "Summarise the information by selecting and reporting the main features, and make comparisons where relevant.", "data": {"years": [2015, 2017, 2019, 2021, 2023], "series": [["Science Museum", [420, 460, 510, 190, 540]], ["History Museum", [380, 360, 340, 120, 300]], ["Art Gallery", [200, 230, 260, 110, 330]]], "unit": "Visitors (thousands)"}}, "W1b": {"task": 1, "chart": "glass", "prompt": "The diagram below shows how glass bottles are recycled.", "instr": "Summarise the information by selecting and reporting the main features, and make comparisons where relevant.", "steps": ["Used bottles are collected in recycling bins", "Bottles are taken to a recycling plant by truck", "Bottles are sorted by colour", "Labels and dirt are washed off", "Glass is crushed into small pieces", "Pieces are melted in a furnace at about 1,500°C", "Molten glass is shaped in moulds", "New bottles are filled and sent to shops"], "icons": ["bin", "truck", "sort", "wash", "crush", "furnace", "mould", "shop"]}, "W2a": {"task": 2, "prompt": "Some people believe that universities should mainly prepare students for employment, while others think the main purpose of a university education is to develop knowledge for its own sake.", "instr": "Discuss both these views and give your own opinion."}, "W2b": {"task": 2, "prompt": "In many countries, more and more people are choosing to live alone.", "instr": "What are the reasons for this? Is this a positive or negative development?"}}, "S": {"Sa": {"p1": {"starts": [0, 4], "topics": ["Your home town", "Reading"], "qs": ["Let's talk about your home town. Where is your home town?", "What do you like most about it?", "Has it changed much since you were a child?", "Would you like to live there in the future? Why, or why not?", "Now let's talk about reading. Do you enjoy reading?", "What kinds of things do you usually read?", "Did you read a lot when you were a child?", "Do you prefer reading paper books or reading on a screen? Why?"]}, "p2": {"title": "Describe a skill that took you a long time to learn.", "points": ["what the skill was", "when and why you started learning it", "how you learned it"], "explain": "and explain how you felt when you were finally able to do it well.", "followup": "Do you still use this skill today?"}, "p3": {"topic": "Learning skills", "qs": ["What skills do young people in your country most want to learn?", "Is it better to learn a skill from a teacher or by yourself? Why?", "Why do some people give up when they are learning a new skill?", "How has technology changed the way people learn practical skills?", "Do you think schools should teach more practical skills? Why, or why not?"]}, "prompts": {"p2intro": "Now I'm going to give you a topic, and I'd like you to talk about it for one to two minutes. Before you talk, you'll have one minute to think about what you're going to say. You can make some notes if you wish.", "p2start": "All right. Remember you have one to two minutes for this. Please start speaking now.", "p2follow": "Thank you. Do you still use this skill today?", "p3intro": "We've been talking about a skill you learned. Now I'd like to discuss with you some more general questions related to this."}, "audio": {"p1": ["audio/Sa_p1_1.mp3", "audio/Sa_p1_2.mp3", "audio/Sa_p1_3.mp3", "audio/Sa_p1_4.mp3", "audio/Sa_p1_5.mp3", "audio/Sa_p1_6.mp3", "audio/Sa_p1_7.mp3", "audio/Sa_p1_8.mp3"], "p3": ["audio/Sa_p3_1.mp3", "audio/Sa_p3_2.mp3", "audio/Sa_p3_3.mp3", "audio/Sa_p3_4.mp3", "audio/Sa_p3_5.mp3"], "p2intro": "audio/Sa_p2intro.mp3", "p2start": "audio/Sa_p2start.mp3", "p2follow": "audio/Sa_p2follow.mp3", "p3intro": "audio/Sa_p3intro.mp3"}}, "Sb": {"p1": {"starts": [0, 3], "topics": ["Work or studies", "Music"], "qs": ["Let's talk about what you do. Do you work, or are you a student?", "Why did you choose that job, or that subject?", "What do you find most difficult about it?", "Now let's talk about music. What kind of music do you like?", "When do you usually listen to music?", "Have you ever learned to play a musical instrument?", "Is music important in the culture of your country?"]}, "p2": {"title": "Describe a place in your city where you like to spend time.", "points": ["where it is", "what it looks like", "what you do there"], "explain": "and explain why you like spending time there.", "followup": "Do your friends like this place too?"}, "p3": {"topic": "Public spaces", "qs": ["What kinds of public places are popular with young people in your country?", "Why are parks important in cities?", "Should public places such as museums be free to enter? Why, or why not?", "How could cities be made more pleasant for the people who live there?", "Do you think people spend less time in public spaces than in the past? Why?"]}, "prompts": {"p2intro": "Now I'm going to give you a topic, and I'd like you to talk about it for one to two minutes. Before you talk, you'll have one minute to think about what you're going to say. You can make some notes if you wish.", "p2start": "All right. Remember you have one to two minutes for this. Please start speaking now.", "p2follow": "Thank you. Do your friends like this place too?", "p3intro": "We've been talking about a place you like. Now I'd like to discuss with you some more general questions related to this."}, "audio": {"p1": ["audio/Sb_p1_1.mp3", "audio/Sb_p1_2.mp3", "audio/Sb_p1_3.mp3", "audio/Sb_p1_4.mp3", "audio/Sb_p1_5.mp3", "audio/Sb_p1_6.mp3", "audio/Sb_p1_7.mp3"], "p3": ["audio/Sb_p3_1.mp3", "audio/Sb_p3_2.mp3", "audio/Sb_p3_3.mp3", "audio/Sb_p3_4.mp3", "audio/Sb_p3_5.mp3"], "p2intro": "audio/Sb_p2intro.mp3", "p2start": "audio/Sb_p2start.mp3", "p2follow": "audio/Sb_p2follow.mp3", "p3intro": "audio/Sb_p3intro.mp3"}}}, "pools": {"L1": ["L1a", "L1b"], "L2": ["L2a", "L2b"], "L3": ["L3a", "L3b"], "L4": ["L4a", "L4b"], "R1": ["R1a", "R1b", "R1c", "R1d", "R1e", "R1f"], "R2": ["R2a", "R2b", "R2c", "R2d", "R2e", "R2f"], "R3": ["R3a", "R3b", "R3c", "R3d", "R3e", "R3f"], "W1": ["W1a", "W1b"], "W2": ["W2a", "W2b"], "S": ["Sa", "Sb"]}};
